    const KageVietSubBridge = {
        initApp() {
            loadUserConfig();
            DeviceCompatibilityManager.detect();
            return { userSettings, mode: DeviceCompatibilityManager.currentMode };
        },
        getUserConfig() {
            return userSettings;
        },
        saveUserConfig(mode, batchSize) {
            saveUserConfig(mode, batchSize);
            return userSettings;
        },
        downloadSamplePrompt() {
            downloadSamplePrompt();
        },
        handleSrtFile(rawText, fileName) {
            const items = parseSrtContent(rawText);
            if (!items || items.length === 0) return null;
            currentSession = initSessionLogic(fileName, items, userSettings.mode, userSettings.batchSize);
            return currentSession;
        },
        async startTranslation() {
            return await startTranslationProcess();
        },
        stopTranslation() {
            if (currentSession) currentSession.stopRequested = true;
        },
        checkSavedSession() {
            return loadSessionFromStorage();
        },
        discardSession() {
            clearSessionStorage();
        },
        saveSession() {
            saveSessionToStorage();
        },
        downloadTranslatedSrt() {
            return downloadTranslatedSrt();
        },
        Position: {
            clamp(left, top, w, h) {
                return PositionManager.clamp(left, top, w, h);
            },
            save(left, top) {
                PositionManager.save(left, top);
            },
            restore(menuEl) {
                return PositionManager.applySaved(menuEl);
            },
            applySaved(menuEl) {
                return PositionManager.applySaved(menuEl);
            },
            attachDrag(headerEl, containerEl) {
                return PositionManager.attachDrag(headerEl, containerEl);
            }
        }
    };

    const PositionManager = {
        STORAGE_KEY: 'kg_pref_widget_position',

        clamp(left, top, elemWidth, elemHeight) {
            const winW = window.innerWidth || document.documentElement.clientWidth || 390;
            const winH = window.innerHeight || document.documentElement.clientHeight || 844;
            return clampPositionLogic(left, top, elemWidth, elemHeight, winW, winH);
        },

        save(left, top) {
            try {
                StorageAdapter.set(this.STORAGE_KEY, { left, top, timestamp: Date.now() });
                console.log(`[PositionManager] Đã lưu vị trí menu: left=${left}px, top=${top}px`);
            } catch (e) {}
        },

        load() {
            const raw = StorageAdapter.get(this.STORAGE_KEY, null);
            return parseSavedPositionLogic(raw);
        },

        applySaved(container) {
            const pos = this.load();
            if (pos && container) {
                const rect = container.getBoundingClientRect();
                const w = rect.width || 350;
                const h = rect.height || 120;
                const clamped = this.clamp(pos.left, pos.top, w, h);
                container.style.left = `${clamped.left}px`;
                container.style.top = `${clamped.top}px`;
                container.style.right = 'auto';
                container.style.bottom = 'auto';
                return true;
            }
            return false;
        },

        attachDrag(headerEl, containerEl) {
            if (!headerEl || !containerEl) return;

            headerEl.style.cursor = 'grab';
            headerEl.style.touchAction = 'none';

            let isDragging = false;
            let startPointerX = 0;
            let startPointerY = 0;
            let startLeft = 0;
            let startTop = 0;
            let hasMoved = false;

            headerEl.addEventListener('pointerdown', (e) => {
                
                if (e.button !== undefined && e.button !== 0) return;

                if (e.target.closest('button, #kg-collapse-btn, #kg-minimize-btn, #kg-vp-toggle-btn, input, select')) {
                    return;
                }

                const rect = containerEl.getBoundingClientRect();
                isDragging = true;
                hasMoved = false;
                startPointerX = e.clientX;
                startPointerY = e.clientY;
                startLeft = rect.left;
                startTop = rect.top;

                headerEl.style.cursor = 'grabbing';
                try {
                    headerEl.setPointerCapture(e.pointerId);
                } catch (err) {}
                e.preventDefault();
            });

            headerEl.addEventListener('pointermove', (e) => {
                if (!isDragging) return;

                const dx = e.clientX - startPointerX;
                const dy = e.clientY - startPointerY;

                if (Math.abs(dx) > 3 || Math.abs(dy) > 3) {
                    hasMoved = true;
                }

                if (hasMoved) {
                    const rect = containerEl.getBoundingClientRect();
                    const winW = window.innerWidth || document.documentElement.clientWidth || 390;
                    const winH = window.innerHeight || document.documentElement.clientHeight || 844;
                    const clamped = calcDragCoordsLogic(startPointerX, startPointerY, startLeft, startTop, e.clientX, e.clientY, rect.width, rect.height, winW, winH);

                    containerEl.style.left = `${clamped.left}px`;
                    containerEl.style.top = `${clamped.top}px`;
                    containerEl.style.right = 'auto';
                    containerEl.style.bottom = 'auto';
                }
            });

            const stopDrag = (e) => {
                if (!isDragging) return;
                isDragging = false;
                headerEl.style.cursor = 'grab';

                try {
                    if (headerEl.hasPointerCapture(e.pointerId)) {
                        headerEl.releasePointerCapture(e.pointerId);
                    }
                } catch (err) {}

                if (hasMoved) {
                    const rect = containerEl.getBoundingClientRect();
                    const clamped = PositionManager.clamp(rect.left, rect.top, rect.width, rect.height);
                    PositionManager.save(clamped.left, clamped.top);
                }
            };

            headerEl.addEventListener('pointerup', stopDrag);
            headerEl.addEventListener('pointercancel', stopDrag);

            window.addEventListener('resize', () => {
                if (containerEl && containerEl.style.left && containerEl.style.left !== 'auto') {
                    const rect = containerEl.getBoundingClientRect();
                    const curLeft = parseInt(containerEl.style.left, 10) || rect.left;
                    const curTop = parseInt(containerEl.style.top, 10) || rect.top;
                    const clamped = PositionManager.clamp(curLeft, curTop, rect.width, rect.height);
                    containerEl.style.left = `${clamped.left}px`;
                    containerEl.style.top = `${clamped.top}px`;
                }
            });
        }
    };

